import StudentCard from "./StudentCard";

function StudentList({ students, deleteStudent }) {
  return students.length === 0
    ? <p>No students</p>
    : students.map(s =>
        <StudentCard key={s.id} student={s} deleteStudent={deleteStudent} />
      );
}

export default StudentList;
